import json
import re

path = '/Data2/v-weilinjin/workshop/AttributeBench/benchmarks/GAIA/2023/validation/bec74516-02fc-48dc-b202-55e78d0e17cf.jsonld'

orcid_re = re.compile(r"\b\d{4}-\d{4}-\d{4}-\d{3}[0-9X]\b")

with open(path, 'r', encoding='utf-8') as f:
    data = json.load(f)

ids = set()

def walk(x):
    if isinstance(x, dict):
        for k, v in x.items():
            if isinstance(v, str):
                if 'orcid.org' in v:
                    m = orcid_re.search(v)
                    if m:
                        ids.add(m.group(0))
            else:
                walk(v)
    elif isinstance(x, list):
        for item in x:
            walk(item)

walk(data)
print(sorted(ids))
